<h1>Posts</h1><p><a class="btn" href="<?= e(url('admin/?action=edit_post')) ?>">Create Post</a></p><?php foreach($posts as $p): ?><div class="card"><h2><?= e($p['title']) ?></h2><p><?= e($p['status']) ?> · <?= e($p['category'] ?? '') ?></p><a class="btn" href="<?= e(url('admin/?action=edit_post&id='.$p['id'])) ?>">Edit</a><form method="post" action="<?= e(url('admin/?action=delete_post&id='.$p['id'])) ?>" style="display:inline"><?= csrf_field() ?><button class="danger">Delete</button></form></div><?php endforeach; ?>
